from fractions import Fraction

def float_to_fraction_string(value: float, max_denominator: int = 12) -> str:
    """Convert a float to a fraction string with limited denominator."""
    # Handle periodic boundary: wrap to [0, 1)
    value = value % 1.0

    # Special case for very small values (essentially 0)
    if abs(value) < 1e-6:
        return "0"
    if abs(value - 1.0) < 1e-6:
        return "0"

    # Convert to fraction
    frac = Fraction(value).limit_denominator(max_denominator)

    if frac.denominator == 1:
        return str(frac.numerator)
    else:
        return f"{frac.numerator}/{frac.denominator}"

# Test with the S coordinates
test_values = [0.38538014, 0.11461986, 0.88538014, 0.0, 0.5, 0.25, 0.333333]
for v in test_values:
    print(f"{v} -> {float_to_fraction_string(v)}")
